-- Function: public.fn_get_board_experience_schedules
-- Backup generated on 2026-10-25 20:33:02

CREATE OR REPLACE FUNCTION public.fn_get_board_experience_schedules(p_tenant_id uuid, p_org_id uuid, p_date date, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, is_celebration boolean, title character varying, time_display character varying, scope_display character varying, status character varying, classroom_id uuid, classroom_name character varying, preparation_notes text)  LANGUAGE sql  STABLE AS $function$     SELECT          es.id,         false AS is_celebration,         COALESCE(e.title, 'Classroom Activity')::varchar AS title,         COALESCE(es.time_of_day, 'Morning')::varchar AS time_display,         cl.name AS scope_display,         es.status AS status,         es.classroom_id AS classroom_id,         cl.name AS classroom_name,         es.preparation_notes AS preparation_notes     FROM experience_schedules es     JOIN classrooms cl ON es.classroom_id = cl.id     JOIN branches b ON cl.branch_id = b.id     LEFT JOIN experiences e ON es.experience_id = e.id     WHERE es.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND es.scheduled_date = p_date       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)     ORDER BY es.planned_start_time NULLS LAST, es.time_of_day; $function$ ;
